<!doctype html><html><head><meta charset="utf-8"><link rel="stylesheet" href="../PRACTICAL-7/style.css"><title>Async CRUD API</title></head><body><main class="box"><h1>Student API (Fetch CRUD)</h1><input id="search" placeholder="Search students"><p id="status"></p><form id="form"><input id="id" type="hidden"><label>Name<input id="name" required></label><label>Email<input id="email" type="email" required></label><label>Course<input id="course" required></label><button>Save</button></form><table id="table"><tr><th>Name</th><th>Email</th><th>Course</th><th>Action</th></tr></table></main><script>
const status=document.querySelector('#status'); async function call(action,data={}){status.textContent='Loading...';let options={};if(action){options={method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...data,action})}}const r=await fetch('api.php'+(action?'':'?q='+encodeURIComponent(search.value)),options);const j=await r.json();if(!r.ok)throw Error(j.data);return j.data}async function load(){try{const rows=await call();table.querySelectorAll('.row').forEach(e=>e.remove());rows.forEach(r=>{table.insertAdjacentHTML('beforeend',`<tr class="row"><td>${r.name}</td><td>${r.email}</td><td>${r.course}</td><td><button onclick='edit(${JSON.stringify(r).replaceAll("'", "&#39;")})'>Edit</button><button onclick="removeStudent(${r.id})">Delete</button></td></tr>`)});status.textContent='Ready';}catch(e){status.textContent=e.message}}form.onsubmit=async e=>{e.preventDefault();try{await call(id.value?'update':'add',{id:Number(id.value),name:name.value,email:email.value,course:course.value});form.reset();load()}catch(e){status.textContent=e.message}};function edit(r){id.value=r.id;name.value=r.name;email.value=r.email;course.value=r.course}async function removeStudent(id){if(confirm('Delete student?')){try{await call('delete',{id});load()}catch(e){status.textContent=e.message}}}search.oninput=load;load();</script></body></html>
